from pathlib import Path
TODAY='2026-06-18'
def header(title): return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"
def write(path,text): Path(path).write_text(text.strip()+"\n", encoding='utf-8')
def article(title,path,pos,concepts,asks,triage,cats,scenarios,analysis):
 c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts)); a='\n'.join(f"- {x}" for x in asks)
 t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage); ca='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in cats)
 sc='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in scenarios); an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
 write(path, header(title)+f'''## 一句话定位\n\n{pos}\n\n## 一、准确解释：三个概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、常见品类与药店咨询口径\n\n| 品类/服务 | 适合讨论的场景 | 药师提醒点 |\n|---|---|---|\n{ca}\n\n## 五、即时零售医药场景拆解\n\n| 场景 | 用户需求 | 平台/药店承接点 |\n|---|---|---|\n{sc}\n\n## 六、对平台、药店、药企的业务分析\n\n{an}\n''')

article('肥胖与GLP1基础概念','08-疾病与医学基础/补充资料/肥胖与GLP1基础概念.md','本文回答：肥胖和GLP-1相关药物为什么不能被简单写成“减肥药即时零售”。核心判断是：肥胖是慢性代谢性问题，GLP-1类药物属于处方和长期管理场景，平台可以承接复购、冷链和药师教育，但不能把体重焦虑转化为自行购药。',
[('肥胖：不是单纯体重数字，而是代谢风险管理','肥胖通常用BMI、腰围和合并症风险评估。它与2型糖尿病、高血压、脂肪肝、睡眠呼吸暂停和心血管风险相关。'),('GLP-1相关药物：处方药和长期管理工具','GLP-1受体激动剂等药物可用于特定适应症或体重管理场景，但需要医生评估、处方、剂量递增和不良反应监测。'),('减重服务：生活方式仍是基础','饮食、运动、睡眠、行为管理和合并症控制仍是长期基础，药物不是单独解决方案。'),('平台风险：搜索热度容易诱发不合规购药','用户可能因社交媒体热度搜索药名，平台必须防止处方药被当作普通减肥商品。')],
['身高体重、BMI、腰围和是否有糖尿病/高血压/脂肪肝等合并症。','是否已有医生处方，药物名称、剂量和使用阶段。','是否出现恶心呕吐、腹痛、脱水、低血糖等不适。','是否孕期、哺乳期、胰腺炎史、胆囊疾病或肾功能异常。','是否存在自行购药、代购或非正规渠道风险。'],
[('稳定处方复购','医生评估后长期管理','处方核验、冷链/库存、用药教育','不引导无处方购买'),('药师重点判断','胃肠反应、剂量不清、合并降糖药','提醒联系医生和监测风险','不自行调剂量'),('优先就医','严重腹痛、持续呕吐脱水、疑似胰腺炎、严重低血糖','提示就医','不靠续购处理')],
[('GLP-1处方药','医生处方下使用','核对适应症、剂量和冷链'),('体重管理用品','体重秤、腰围、饮食记录','辅助管理'),('药师咨询','不良反应和用药教育','提醒复诊'),('生活方式服务','饮食运动管理','不替代治疗')],
[('处方复购','不断药','处方/冷链/库存'),('副作用咨询','胃肠反应','药师提示和医生联系'),('体重管理','长期记录','工具和教育'),('风险拦截','无处方购药','合规拦截')],
[('平台','GLP-1入口必须以处方核验和风险教育优先，不能做普通减肥商品转化。'),('药店','药师应关注冷链、剂量、胃肠反应和合并降糖药风险。'),('药企','教育重点应是规范适应症、长期管理和不良反应识别。')])

article('处方药OTC适应症禁忌症不良反应','08-疾病与医学基础/补充资料/处方药OTC适应症禁忌症不良反应.md','本文回答：处方药、OTC、适应症、禁忌症和不良反应这些药品基础概念如何用于药店咨询。核心判断是：药品信息不能只讲“治什么”，还必须同时讲“谁不能用”“可能有什么风险”“什么时候应就医”。',
[('处方药和OTC：区别在风险管理和获取条件','处方药需要医生处方或处方流转链路，OTC可在说明书范围内自我选择。OTC并不等于绝对安全，处方药也不能因为平台有货就自行购买。'),('适应症：药品被批准用于什么情况','适应症不是用户自我诊断。用户觉得“症状像”不等于符合适应症。'),('禁忌症和慎用：决定哪些人不能简单购买','儿童、孕妇、肝肾功能异常、过敏史、多药联用等都可能影响药品选择。'),('不良反应：不是小概率就可以忽略','药师咨询应提醒常见不良反应、严重不良反应信号和出现异常时如何处理。')],
['药品是处方药还是OTC，用户是否有处方。','用户想解决的症状或疾病是否符合说明书适应症。','是否有禁忌、过敏、特殊人群或多药联用。','是否已经出现不良反应或疗效不佳。','是否需要医生诊断、复诊或监测。'],
[('可自我选择','OTC且说明书适用、无禁忌','说明书教育和药师咨询','不越过适应症'),('药师重点判断','适应症不清、特殊人群、多药联用','核对禁忌和不良反应','不替代医生开方'),('优先就医','严重不良反应、症状加重、处方药无处方','提示就医/医生确认','不继续推荐购买')],
[('OTC','轻症和常备','核对适应症和禁忌'),('处方药','医生处方下使用','不自行启停'),('说明书教育','用户不理解用法','解释剂量频次和风险'),('药师咨询','边界不清','风险分层')],
[('搜索药名','用户找具体药','处方/OTC识别'),('症状购药','用户不知道买什么','先分层'),('复购','历史订单','核对处方和不良反应'),('风险拦截','禁忌/不良反应','就医提示')],
[('平台','药品页要同时呈现适应症、禁忌症、不良反应和处方边界。'),('药店','药师咨询要从“能卖”转向“是否适合”。'),('药企','说明书教育是合规内容资产，不应只强调疗效。')])

article('PubMed慢病与社区药房文献索引','08-疾病与医学基础/补充资料/PubMed慢病与社区药房文献索引.md','本文回答：PubMed慢病与社区药房文献索引应该如何服务信息库研究。核心判断是：文献索引不是结论库，而是帮助查找社区药房在慢病管理、依从性、药师干预和患者教育方面证据的研究入口。',
[('PubMed文献：用于找证据，不直接复制结论','PubMed收录医学文献，但单篇研究的设计、样本、国家和结局不同，不能直接套到中国药店或平台买药。'),('社区药房研究：重点看药师干预和患者结局','常见主题包括血压管理、糖尿病教育、用药依从性、疫苗、戒烟、药物治疗管理和药师随访。'),('慢病管理证据：要看干预方式和终点','专业阅读应区分随机试验、观察研究、综述和指南；看的是血压、HbA1c、依从性、住院率等终点。'),('平台转化：文献启发服务设计，不等于商业结论','文献可启发药师服务和随访模型，但不能直接证明某平台业务有效。')],
['研究对象是哪类患者和哪类药房。','干预是什么：药师教育、随访、用药审查还是监测。','结局是什么：指标改善、依从性、就医、成本还是满意度。','研究在哪个国家和医疗体系，是否能迁移到本地。','证据等级如何，是否有系统综述或指南支持。'],
[('可参考','主题与慢病药师服务相关','提炼研究问题和服务模型','不直接当本地结论'),('需深入评估','样本小、场景不同、结局复杂','阅读全文和方法','不只看摘要'),('不宜使用','与标题无关或证据弱','不纳入文章结论','不做确定判断')],
[('文献索引','研究入口','标注主题和证据类型'),('药师服务模型','慢病管理设计','看干预和终点'),('业务假设','平台服务启发','需本地数据验证'),('内部培训','提升专业理解','不替代指南')],
[('选题研究','找慢病药师服务证据','检索词和主题分类'),('服务设计','设计随访项目','借鉴干预方式'),('内容审核','支撑医学表述','核对证据'),('业务评估','验证效果','需要本地数据')],
[('平台','可用文献设计药师服务，但不能把研究结果直接写成平台效果。'),('药店','社区药房证据可帮助设计随访、依从性和用药审查。'),('药企','可用文献支持患者教育项目，但需要本地化验证。')])

article('医学基础资料使用说明','08-疾病与医学基础/补充资料/医学基础资料引用边界说明.md','本文回答：医学基础资料在信息库里应该怎样使用。核心判断是：医学基础资料用于建立概念、风险分层、药师咨询和就医提醒框架，不用于替代诊断、处方或个体化治疗建议。',
[('医学基础：解释概念和场景','医学基础文章应说明疾病或症状是什么、常见表现、风险信号和药店咨询问题。'),('药店咨询：识别风险和解释说明书','药师咨询的价值是帮助用户理解用药边界、特殊人群和什么时候就医。'),('即时零售：提高可得性和解释效率','平台可以提供库存、配送、药师在线和内容教育，但不能替代医生判断。'),('业务分析：必须建立在医学分层之后','平台、药店、药企分析必须从医学风险和服务链路推导，不能先写商业机会。')],
['标题承诺的是疾病、症状、用药、特殊人群还是场景。','文章是否先解释概念，再讲咨询和业务。','是否列出红旗信号和特殊人群。','是否避免诊断和具体治疗方案。','是否删除不相关来源和泛化内容。'],
[('合格资料','概念清楚、分层完整','用于内部学习和生成文章','不替代诊疗'),('需药师判断','涉及药品选择或特殊人群','强调说明书和就医','不写个体方案'),('不可使用','来源错配、夸大疗效、无红旗信号','退回重写','不发布')],
[('概念解释','疾病/症状定义','写清楚层级'),('风险分层','红旗信号','就医优先'),('品类咨询','OTC/处方药/用品','说明边界'),('业务分析','平台药店药企','从医学推导')],
[('文章生成','按标题研究','先医学后业务'),('内容审核','查泛化和错配','逐项修正'),('培训使用','帮助团队理解','不作诊疗'),('平台设计','风险拦截','安全优先')],
[('平台','医学基础内容应支持风险拦截和药师咨询，而不是只支持转化。'),('药店','资料应变成可执行问询模板。'),('药企','资料可用于合规教育，不应替代适应症证据。')])

